package srs

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"sort"

	"gopkg.in/yaml.v3"
)

// Problem is the facts about one sheet row. problems.yml, keyed by LeetCode slug —
// generated by setup, so it can be rebuilt.
type Problem struct {
	Name       string `yaml:"name"`
	Topic      string `yaml:"topic"`
	Difficulty string `yaml:"difficulty"`
	PaidOnly   bool   `yaml:"paid_only"`
	Link       string `yaml:"link"`
	AltLink    string `yaml:"alt_link,omitempty"` // NeetCode's free version of a premium problem
	File       string `yaml:"file"`               // solution file, relative to the repo root
	Order      int    `yaml:"order"`              // row position in the sheet
	Notes      string `yaml:"notes,omitempty"`
}

type Problems map[string]*Problem

type HistoryEntry struct {
	Date  Date   `yaml:"date"`
	Grade string `yaml:"grade"` // again | hard | good | easy, or seed for setup's
}

// Card is the SM-2 schedule of one problem the user has seen.
type Card struct {
	Reps         int            `yaml:"reps"`
	Ease         float64        `yaml:"ease"`
	Interval     int            `yaml:"interval"`
	LastReviewed Date           `yaml:"last_reviewed,omitempty"`
	NextReview   Date           `yaml:"next_review,omitempty"`
	History      []HistoryEntry `yaml:"history"`
}

// Entry is one slot of the day.
type Entry struct {
	Slug   string `yaml:"slug,omitempty"` // empty: nothing eligible for this slot
	Kind   string `yaml:"kind,omitempty"` // new | review | early
	Forced bool   `yaml:"forced"`
	Grade  string `yaml:"grade,omitempty"`
	Chosen bool   `yaml:"chosen,omitempty"` // picked by the user with `start <file|slug>`
}

// Session is today's picks, saved so `today` shows the same ones all day.
type Session struct {
	Date  Date              `yaml:"date"`
	Slots map[string]*Entry `yaml:"slots"`
}

// State is the user's review history: state.yml. Only grading and the session change it.
// A problem is "seen" if it has a card.
type State struct {
	Problems       map[string]*Card `yaml:"problems"`
	LastNewOn      Date             `yaml:"last_new_on,omitempty"`
	NextForcedPool string           `yaml:"next_forced_pool"`
	Session        *Session         `yaml:"session,omitempty"`
}

func DefaultState() *State {
	return &State{Problems: map[string]*Card{}, NextForcedPool: "medium_hard"}
}

func (e *Entry) Empty() bool { return e.Slug == "" }

// LoadProblems errors when problems.yml is missing, since nothing works without it.
func LoadProblems(path string) (Problems, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	problems := Problems{}
	if err := yaml.Unmarshal(data, &problems); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return problems, nil
}

// LoadState returns a fresh state when the file doesn't exist yet.
func LoadState(path string) (*State, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return DefaultState(), nil
	}
	if err != nil {
		return nil, err
	}
	state := DefaultState()
	if err := yaml.Unmarshal(data, state); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	if state.Problems == nil {
		state.Problems = map[string]*Card{}
	}
	return state, nil
}

func SaveState(path string, state *State) error {
	return writeYAML(path, state)
}

// SaveProblems writes the problems in sheet order, which a plain map wouldn't keep.
func SaveProblems(path string, problems Problems) error {
	root := &yaml.Node{Kind: yaml.MappingNode}
	for _, slug := range problems.Slugs() {
		value := &yaml.Node{}
		if err := value.Encode(problems[slug]); err != nil {
			return err
		}
		root.Content = append(root.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: slug}, value)
	}
	return writeYAML(path, root)
}

// Slugs lists the problems in sheet order.
func (p Problems) Slugs() []string {
	slugs := make([]string, 0, len(p))
	for slug := range p {
		slugs = append(slugs, slug)
	}
	sort.Slice(slugs, func(i, j int) bool { return p[slugs[i]].Order < p[slugs[j]].Order })
	return slugs
}

// writeYAML writes to a temp file and renames it, so an interrupted run can't
// leave state.yml half-written.
func writeYAML(path string, data any) error {
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(data); err != nil {
		return err
	}
	if err := enc.Close(); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, buf.Bytes(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}
